-- ============================================================================
-- 0009_question_quota.sql
-- ============================================================================
-- Hazel Quest — per-player request log + quota for generate-questions (#88)
-- Run in the Supabase SQL Editor (or `supabase db push`) after 0008.
--
-- The edge function calls the Claude API on the project's key, so an
-- unthrottled caller could run up the bill. Every call is logged here and
-- checked by `begin_question_request`:
--   * a per-player request rate (calls per minute) → over it: 429
--   * a per-player daily budget of FRESH (Claude-generated) questions
--   * a project-wide daily budget of fresh questions (the real cost ceiling)
-- When a fresh budget is spent the function still serves cached questions,
-- so kids keep playing from the shared bank. The `questions` bank itself is
-- never pruned (product decision, ISSUES #68).

create table if not exists public.question_requests (
  id           bigint      generated always as identity primary key,
  profile_id   uuid        not null references auth.users (id) on delete cascade,
  requested_at timestamptz not null default now(),
  -- Filled in after generation: how many questions actually came from Claude.
  fresh_count  integer     not null default 0
);

-- Lookup patterns: one player's recent calls; everyone's calls in the last day.
create index if not exists question_requests_profile_time_idx
  on public.question_requests (profile_id, requested_at desc);
create index if not exists question_requests_time_idx
  on public.question_requests (requested_at);

alter table public.question_requests enable row level security;
-- No client policies: only the edge function (service role) touches this.
grant select, insert, update on public.question_requests to service_role;

-- Atomically check the caller's quota and log the call. Serialized per player
-- with an advisory lock, so a burst of parallel calls can't all slip under
-- the limit. Returns:
--   allowed         false → over the per-minute rate (caller returns 429)
--   fresh_allowance how many fresh questions this call may generate (≥ 0)
--   request_id      the log row; the caller records fresh_count on it
create or replace function public.begin_question_request(
  p_profile         uuid,
  p_max_per_minute  integer,
  p_fresh_per_day   integer,
  p_fresh_global    integer
)
returns table (allowed boolean, fresh_allowance integer, request_id bigint)
language plpgsql
set search_path = public
as $$
declare
  v_recent       integer;
  v_fresh_mine   integer;
  v_fresh_all    integer;
  v_id           bigint;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_profile::text, 0));

  select count(*) into v_recent
    from question_requests
   where profile_id = p_profile
     and requested_at > now() - interval '1 minute';

  if v_recent >= p_max_per_minute then
    return query select false, 0, null::bigint;
    return;
  end if;

  select coalesce(sum(fresh_count), 0) into v_fresh_mine
    from question_requests
   where profile_id = p_profile
     and requested_at > now() - interval '1 day';

  select coalesce(sum(fresh_count), 0) into v_fresh_all
    from question_requests
   where requested_at > now() - interval '1 day';

  insert into question_requests (profile_id) values (p_profile)
  returning id into v_id;

  return query select
    true,
    greatest(0, least(p_fresh_per_day - v_fresh_mine, p_fresh_global - v_fresh_all))::integer,
    v_id;
end;
$$;

-- Supabase grants EXECUTE on new public functions to anon + authenticated by
-- default; revoke so a client can never burn another player's quota.
revoke all on function public.begin_question_request(uuid, integer, integer, integer)
  from public, anon, authenticated;
grant execute on function public.begin_question_request(uuid, integer, integer, integer) to service_role;

insert into supabase_migrations.schema_migrations (version, name, statements)
values ('0009', 'question_quota', array[]::text[])
on conflict (version) do nothing;

-- ============================================================================
-- 0010_access_hardening.sql
-- ============================================================================
-- Hazel Quest — access hardening from the migrations review (#90)
-- Run in the Supabase SQL Editor (or `supabase db push`) after 0009.
-- Re-runnable, like every migration (see CLAUDE.md → migrations rules).
--
-- Fixes are a NEW migration instead of edits to 0001/0003: projects that
-- already recorded 0001/0003 (e.g. via `supabase db push`) would never re-run
-- an edited old file, so the fix has to arrive as the next version.

-- 1) profiles had no explicit table grants. The client reads/inserts/updates
--    its own row (profileStore), protected by 0001's RLS policies; on a
--    project with tightened public-schema defaults (see 0005/0008) every
--    profile write failed with "permission denied" and XP never saved.
--    Mirrors 0008's grants for `saves`. RLS still limits rows to the owner.
grant select, insert, update on public.profiles to authenticated;
grant select, insert, update on public.profiles to service_role;

-- 2) The sign-up trigger required birth-date metadata: creating a user from
--    the dashboard, an invite, or a future OAuth / parent-account flow failed
--    the whole sign-up ("Database error saving new user"). Now it only seeds
--    the profile when both values are present and valid; otherwise the app
--    creates the row on first load (profileStore.loadProfile) with a default
--    age. `on conflict do nothing` keeps it safe if a row already exists.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_year  text := new.raw_user_meta_data ->> 'birth_year';
  v_month text := new.raw_user_meta_data ->> 'birth_month';
begin
  if v_year ~ '^\d{4}$' and v_month ~ '^\d{1,2}$' and v_month::int between 1 and 12 then
    insert into public.profiles (id, birth_year, birth_month)
    values (new.id, v_year::smallint, v_month::smallint)
    on conflict (id) do nothing;
  end if;
  return new;
end;
$$;

-- 3) increment_question_usage stayed callable by everyone through Postgres's
--    default PUBLIC execute grant (0003 only revoked anon/authenticated).
--    Harmless today (invoker rights + RLS → 0 rows), but only the edge
--    function should call it. 0005 already grants it to service_role.
revoke execute on function public.increment_question_usage(uuid[]) from public, anon, authenticated;
grant execute on function public.increment_question_usage(uuid[]) to service_role;

insert into supabase_migrations.schema_migrations (version, name, statements)
values ('0010', 'access_hardening', array[]::text[])
on conflict (version) do nothing;

-- ============================================================================
-- 0011_save_version_guard.sql
-- ============================================================================
-- Hazel Quest — an older game can never overwrite a newer save (#101h)
-- Run in the Supabase SQL Editor (or `supabase db push`) after 0010.
-- Re-runnable, like every migration (see CLAUDE.md → migrations rules).
--
-- Each save records the version of its shape (`data->>'version'`;
-- `SAVE_VERSION` in src/lib/save.ts — 2 since #75 item 8). A client already
-- refuses to LOAD a save from a newer version than itself, but a tab that was
-- open when a newer version shipped still has its older save in memory, and
-- its next upload would replace the newer save. This trigger refuses any
-- update that would lower a save's version; the client then shows "refresh to
-- update" (saveStore: the error code `save_version_conflict`).
--
-- A save without a numeric version (or with junk there) counts as version 1,
-- as the client reads it (`saveVersionOf`).

create or replace function public.saves_keep_newest_version()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_old integer := case when jsonb_typeof(old.data -> 'version') = 'number'
                         and (old.data ->> 'version') ~ '^\d{1,9}$'
                        then (old.data ->> 'version')::integer else 1 end;
  v_new integer := case when jsonb_typeof(new.data -> 'version') = 'number'
                         and (new.data ->> 'version') ~ '^\d{1,9}$'
                        then (new.data ->> 'version')::integer else 1 end;
begin
  if v_new < v_old then
    raise exception 'save_version_conflict: this save was written by a newer version of the game (v%), refusing v%',
      v_old, v_new
      using hint = 'Refresh the page to update the game.';
  end if;
  return new;
end;
$$;

drop trigger if exists saves_keep_newest_version on public.saves;
create trigger saves_keep_newest_version
  before update on public.saves
  for each row execute function public.saves_keep_newest_version();

insert into supabase_migrations.schema_migrations (version, name, statements)
values ('0011', 'save_version_guard', array[]::text[])
on conflict (version) do nothing;

-- ============================================================================
-- 0012_save_player_level.sql
-- ============================================================================
-- Hazel Quest — save the player's level
-- Run in the Supabase SQL Editor (or `supabase db push`) after 0011.
--
-- The level used to be derived from total XP (a flat 100 XP per level), so
-- changing the curve would have moved every player's level. Now the level is
-- stored, with the XP earned toward the next one (src/lib/level.ts):
--   level     — the player's level, never lowered by a curve change.
--   level_xp  — XP earned into the current level.
-- `xp` stays the lifetime total.
--
-- Existing rows are backfilled from the old flat curve, so every player keeps
-- exactly the level they had. Re-runnable: the backfill only touches rows
-- that have no level yet.

alter table public.profiles
  add column if not exists level    integer,
  add column if not exists level_xp integer;

update public.profiles
   set level    = greatest(xp, 0) / 100 + 1,
       level_xp = greatest(xp, 0) % 100
 where level is null or level_xp is null;

alter table public.profiles
  alter column level    set default 1,
  alter column level    set not null,
  alter column level_xp set default 0,
  alter column level_xp set not null;

insert into supabase_migrations.schema_migrations (version, name, statements)
values ('0012', 'save_player_level', array[]::text[])
on conflict (version) do nothing;

-- ============================================================================
-- 0013_parent_accounts.sql
-- ============================================================================
-- Hazel Quest — parent accounts (#124, ISSUES #89)
-- Run in the Supabase SQL Editor (or `supabase db push`) after 0012.
-- Re-runnable, like every migration (see CLAUDE.md → migrations rules).
--
-- A login now belongs to a grown-up, who adds their kids. Each kid is a row in
-- `profiles` with its own id and `parent_id` = the grown-up's login; a kid's
-- save and flags are reachable only through that grown-up. Kids never get an
-- email or a login of their own.
--
-- Accounts from before this become a grown-up with one kid: the profile keeps
-- its id (= the login's id), so its save, its seen questions and the app's
-- local caches all still match. Their `parents` row has no consent yet, so the
-- app asks a grown-up for it at the next sign-in.
--
-- Backward compatible: the app from before this keeps working (its profile is
-- still found by the login's id, and its sign-up still makes that first kid).

-- 1) Grown-ups and their consent.
create table if not exists public.parents (
  id              uuid        primary key references auth.users (id) on delete cascade,
  -- When, and to which wording, the grown-up agreed (null = not yet: the app asks).
  consent_at      timestamptz,
  consent_version text,
  created_at      timestamptz not null default now()
);

alter table public.parents enable row level security;

drop policy if exists "Grown-ups read their own row" on public.parents;
create policy "Grown-ups read their own row"
  on public.parents for select
  using (auth.uid() = id);

grant select on public.parents to authenticated;
grant select, insert, update on public.parents to service_role;

-- The app writes this table only through here: consent is stamped with the
-- server's clock (the client can't backdate it), and a login from before this
-- with no kid — so no row from step 2 — gets its row on agreeing.
create or replace function public.record_consent(p_version text)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.parents (id, consent_at, consent_version)
  values (auth.uid(), now(), left(p_version, 40))
  on conflict (id) do update
    set consent_at = now(), consent_version = left(p_version, 40);
$$;
revoke execute on function public.record_consent(text) from public, anon;
grant execute on function public.record_consent(text) to authenticated;

-- 2) Kids: a profile gets a grown-up, a nickname, a tile picture and a secret
--    picture (what a kid taps to open their own profile on a shared device —
--    a lock against a sibling's slip, not a password: the grown-up's session
--    can read it).
alter table public.profiles
  add column if not exists parent_id        uuid references auth.users (id) on delete cascade,
  add column if not exists display_name     text,
  add column if not exists icon             text,
  add column if not exists picture_password text;

-- Profiles from before this are their own login's first kid.
update public.profiles set parent_id = id where parent_id is null;
alter table public.profiles alter column parent_id set not null;
-- A kid added by the app belongs to whoever is signed in (an app from before
-- this, creating a missing profile, gets the same).
alter table public.profiles alter column parent_id set default auth.uid();
create index if not exists profiles_parent_idx on public.profiles (parent_id);

-- A kid isn't a login: new kids get their own id. (An existing kid keeps
-- theirs; deleting the login still removes them, through parent_id.)
alter table public.profiles drop constraint if exists profiles_id_fkey;
alter table public.profiles alter column id set default gen_random_uuid();

alter table public.profiles drop constraint if exists profiles_display_name_length;
alter table public.profiles add constraint profiles_display_name_length
  check (display_name is null or char_length(btrim(display_name)) between 1 and 20);

-- Every grown-up who already has a kid gets their row (no consent yet).
insert into public.parents (id)
  select distinct parent_id from public.profiles
  on conflict (id) do nothing;

-- 3) Kids belong to their grown-up: read, add, change and remove them.
drop policy if exists "Profiles are viewable by their owner" on public.profiles;
drop policy if exists "Users can insert their own profile" on public.profiles;
drop policy if exists "Users can update their own profile" on public.profiles;

drop policy if exists "Grown-ups see their kids" on public.profiles;
create policy "Grown-ups see their kids"
  on public.profiles for select
  using (auth.uid() = parent_id);

drop policy if exists "Grown-ups add kids" on public.profiles;
create policy "Grown-ups add kids"
  on public.profiles for insert
  with check (auth.uid() = parent_id);

drop policy if exists "Grown-ups update their kids" on public.profiles;
create policy "Grown-ups update their kids"
  on public.profiles for update
  using (auth.uid() = parent_id)
  with check (auth.uid() = parent_id);

-- Removing a kid removes their save, seen questions and flags with them
-- (each references profiles on delete cascade).
drop policy if exists "Grown-ups remove kids" on public.profiles;
create policy "Grown-ups remove kids"
  on public.profiles for delete
  using (auth.uid() = parent_id);

grant delete on public.profiles to authenticated;

-- A kid's save: their grown-up's to read and write.
drop policy if exists "Players read their own save" on public.saves;
drop policy if exists "Players create their own save" on public.saves;
drop policy if exists "Players update their own save" on public.saves;

drop policy if exists "Grown-ups read their kids' saves" on public.saves;
create policy "Grown-ups read their kids' saves"
  on public.saves for select
  using (exists (select 1 from public.profiles p where p.id = profile_id and p.parent_id = auth.uid()));

drop policy if exists "Grown-ups create their kids' saves" on public.saves;
create policy "Grown-ups create their kids' saves"
  on public.saves for insert
  with check (exists (select 1 from public.profiles p where p.id = profile_id and p.parent_id = auth.uid()));

drop policy if exists "Grown-ups update their kids' saves" on public.saves;
create policy "Grown-ups update their kids' saves"
  on public.saves for update
  using (exists (select 1 from public.profiles p where p.id = profile_id and p.parent_id = auth.uid()))
  with check (exists (select 1 from public.profiles p where p.id = profile_id and p.parent_id = auth.uid()));

-- A flag is sent as one of the grown-up's kids.
drop policy if exists "users insert their own flags" on public.question_flags;
drop policy if exists "Grown-ups flag as their kids" on public.question_flags;
create policy "Grown-ups flag as their kids"
  on public.question_flags for insert
  to authenticated
  with check (exists (select 1 from public.profiles p where p.id = profile_id and p.parent_id = auth.uid()));

-- 4) Sign-up: every new login is a grown-up. Agreeing on the sign-up form
--    (`consent_version` in the metadata) is stamped now; without it the app
--    asks before anyone plays. An app from before this still sends a birth
--    date and no consent: that login gets its first kid, as old accounts did.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_year    text := new.raw_user_meta_data ->> 'birth_year';
  v_month   text := new.raw_user_meta_data ->> 'birth_month';
  v_consent text := new.raw_user_meta_data ->> 'consent_version';
begin
  if v_consent !~ '^[A-Za-z0-9._-]{1,40}$' then
    v_consent := null;
  end if;
  insert into public.parents (id, consent_at, consent_version)
  values (new.id, case when v_consent is not null then now() end, v_consent)
  on conflict (id) do nothing;

  if v_year ~ '^\d{4}$' and v_month ~ '^\d{1,2}$' and v_month::int between 1 and 12 then
    insert into public.profiles (id, parent_id, birth_year, birth_month)
    values (new.id, new.id, v_year::smallint, v_month::smallint)
    on conflict (id) do nothing;
  end if;
  return new;
end;
$$;

insert into supabase_migrations.schema_migrations (version, name, statements)
values ('0013', 'parent_accounts', array[]::text[])
on conflict (version) do nothing;

-- ============================================================================
-- 0014_pins_and_kid_budget.sql
-- ============================================================================
-- Hazel Quest — PINs and a question budget per kid (#124)
-- Run in the Supabase SQL Editor (or `supabase db push`) after 0013.
-- Re-runnable, like every migration (see CLAUDE.md → migrations rules).
--
-- The owner's calls (2026-10-10): every kid opens their profile with a
-- 4-digit PIN (replacing 0013's secret picture); 👪 Grown-ups opens with the
-- grown-up's own PIN or their password; the question budget is per kid.
--
-- PINs are stored hashed (bcrypt, pgcrypto) in tables no client can read or
-- write; the app sets and checks them only through the functions below, which
-- also check the kid is the caller's.

-- pgcrypto: already in `extensions` on Supabase; created here for plain Postgres (CI).
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;

-- 1) Kid PINs.
create table if not exists public.kid_pins (
  profile_id uuid        primary key references public.profiles (id) on delete cascade,
  pin_hash   text        not null,
  updated_at timestamptz not null default now()
);
-- RLS on and no policies, no grants: only the security-definer functions get in.
alter table public.kid_pins enable row level security;
revoke all on public.kid_pins from anon, authenticated;

-- What the app may know: whether a kid has a PIN (not the PIN).
alter table public.profiles add column if not exists has_pin boolean not null default false;

-- The secret picture is replaced by the PIN.
alter table public.profiles drop column if exists picture_password;

create or replace function public.set_kid_pin(p_kid uuid, p_pin text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_pin is null or p_pin !~ '^\d{4}$' then
    raise exception 'pin_format: a PIN is 4 digits';
  end if;
  if not exists (select 1 from public.profiles where id = p_kid and parent_id = auth.uid()) then
    raise exception 'not_your_kid: that player belongs to another account';
  end if;
  insert into public.kid_pins (profile_id, pin_hash)
  values (p_kid, extensions.crypt(p_pin, extensions.gen_salt('bf')))
  on conflict (profile_id) do update set pin_hash = excluded.pin_hash, updated_at = now();
  update public.profiles set has_pin = true where id = p_kid;
end;
$$;

create or replace function public.check_kid_pin(p_kid uuid, p_pin text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
      from public.kid_pins k
      join public.profiles p on p.id = k.profile_id
     where k.profile_id = p_kid
       and p.parent_id = auth.uid()
       and k.pin_hash = extensions.crypt(p_pin, k.pin_hash)
  );
$$;

-- 2) The grown-up's own PIN (optional: their password always works too).
create table if not exists public.parent_pins (
  id         uuid        primary key references auth.users (id) on delete cascade,
  pin_hash   text        not null,
  updated_at timestamptz not null default now()
);
alter table public.parent_pins enable row level security;
revoke all on public.parent_pins from anon, authenticated;

-- Readable by the grown-up (`parents` has no update grant, so only
-- set_parent_pin changes it).
alter table public.parents add column if not exists has_pin boolean not null default false;

create or replace function public.set_parent_pin(p_pin text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_pin is null or p_pin !~ '^\d{4}$' then
    raise exception 'pin_format: a PIN is 4 digits';
  end if;
  insert into public.parent_pins (id, pin_hash)
  values (auth.uid(), extensions.crypt(p_pin, extensions.gen_salt('bf')))
  on conflict (id) do update set pin_hash = excluded.pin_hash, updated_at = now();
  insert into public.parents (id, has_pin) values (auth.uid(), true)
  on conflict (id) do update set has_pin = true;
end;
$$;

create or replace function public.check_parent_pin(p_pin text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.parent_pins
     where id = auth.uid() and pin_hash = extensions.crypt(p_pin, pin_hash)
  );
$$;

revoke execute on function public.set_kid_pin(uuid, text) from public, anon;
revoke execute on function public.check_kid_pin(uuid, text) from public, anon;
revoke execute on function public.set_parent_pin(text) from public, anon;
revoke execute on function public.check_parent_pin(text) from public, anon;
grant execute on function public.set_kid_pin(uuid, text) to authenticated;
grant execute on function public.check_kid_pin(uuid, text) to authenticated;
grant execute on function public.set_parent_pin(text) to authenticated;
grant execute on function public.check_parent_pin(text) to authenticated;

-- 3) The question budget is per kid: begin_question_request's p_profile is
--    now the kid's id (the edge function sends it). Requests point at the kid
--    and go when the kid is removed. NOT VALID: rows logged under a login
--    before this are left as they are (they age out of every window in a day).
alter table public.question_requests drop constraint if exists question_requests_profile_id_fkey;
alter table public.question_requests drop constraint if exists question_requests_kid_fkey;
alter table public.question_requests add constraint question_requests_kid_fkey
  foreign key (profile_id) references public.profiles (id) on delete cascade not valid;

-- A per-kid budget would grow with every kid added, so a family has at most 8.
create or replace function public.profiles_kid_limit()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select count(*) from public.profiles where parent_id = new.parent_id) >= 8 then
    raise exception 'kid_limit: a family account can have up to 8 players';
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_kid_limit on public.profiles;
create trigger profiles_kid_limit
  before insert on public.profiles
  for each row execute function public.profiles_kid_limit();

insert into supabase_migrations.schema_migrations (version, name, statements)
values ('0014', 'pins_and_kid_budget', array[]::text[])
on conflict (version) do nothing;

-- ============================================================================
-- 0015_fair_question_reuse.sql
-- ============================================================================
-- Hazel Quest — fairer question reuse (#134)
-- Run in the Supabase SQL Editor (or `supabase db push`) after 0014.
-- Re-runnable, like every migration (see CLAUDE.md → migration rules).
--
-- The owner's calls (2026-10-12), three fixes to how generate-questions
-- reuses its bank:
--
-- 1) The bank was read 200 rows at a time with no ORDER BY, so Postgres
--    handed back the same (oldest) 200 of a level band on every call: past
--    200 a band's new questions were never reused. pick_cached_questions
--    samples the WHOLE band at random, leaning toward less-asked questions
--    (weight 1/sqrt(1 + times_asked)) so the bank gets used evenly, without
--    always serving the newest (least-flagged) ones first.
-- 2) A question records the age it was written for; reuse skips one written
--    for a child more than a year older (the function is given the oldest
--    age allowed). Questions from before this have no age and stay reusable.
-- 3) "Seen" means shown. The app marks a question seen when it's on screen
--    (mark_questions_seen). A question delivered but not shown yet (fetched
--    ahead for a battle that may never happen) is only held back from that
--    kid for a while (p_reserve), and never pushes questions they really saw
--    out of the window — which is now per topic (the last p_seen_limit shown
--    in that topic), not the last 100 of any topic.

-- 2) The age a question was written for (null = from before this).
alter table public.questions add column if not exists age smallint;

-- 3) A view the app reported as shown (true), or a delivery not shown yet
--    (false). Rows from before this were deliveries counted as seen: true.
alter table public.question_views add column if not exists shown boolean not null default true;

-- 1–3) Up to p_limit reusable questions for one topic and level band, in a
-- random order leaning to less-asked, unseen first. `seen` marks the ones this
-- kid saw lately (or was just handed) — the edge function uses those only when
-- its fresh budget can't fill the batch. Flagged questions never come back.
create or replace function public.pick_cached_questions(
  p_topic      text,
  p_min_level  integer,
  p_max_level  integer,
  p_max_age    integer,
  p_profile    uuid,
  p_seen_limit integer,
  p_reserve    interval,
  p_limit      integer
)
returns table (
  id            uuid,
  level         smallint,
  text          text,
  options       jsonb,
  correct_index smallint,
  explanation   text,
  times_asked   integer,
  seen          boolean
)
language sql
set search_path = public
as $$
  with recent as (
    -- The kid's latest shown views of any topic, read newest first off the
    -- (profile_id, seen_at desc) index and capped, so a call costs the same
    -- however long they've played (no scan of their whole history).
    select v.question_id, v.seen_at
      from question_views v
     where v.profile_id = p_profile
       and v.shown
     order by v.seen_at desc
     limit greatest(p_seen_limit, 0) * 10
  ),
  shown as (
    select r.question_id
      from recent r
      join questions q on q.id = r.question_id
     where q.topic = p_topic
     -- A question shown again (a battle goes round its pool) counts once.
     group by r.question_id
     order by max(r.seen_at) desc
     limit greatest(p_seen_limit, 0)
  ),
  held as (
    select question_id from shown
    union
    select v.question_id
      from question_views v
     where v.profile_id = p_profile
       and not v.shown
       and v.seen_at > now() - p_reserve
  )
  select q.id, q.level, q.text, q.options, q.correct_index, q.explanation, q.times_asked,
         (h.question_id is not null) as seen
    from questions q
    left join held h on h.question_id = q.id
   where q.topic = p_topic
     and q.level between p_min_level and p_max_level
     and (p_max_age is null or q.age is null or q.age <= p_max_age)
     and not exists (select 1 from question_flags f where f.question_id = q.id)
   order by (h.question_id is not null),
            -- Weighted random order (Efraimidis–Spirakis): the smallest key
            -- wins; 1 - random() is never 0, so ln() always has an answer.
            -ln(1 - random()) * sqrt(1 + greatest(q.times_asked, 0))
   limit greatest(p_limit, 0);
$$;

-- Only the edge function reads the bank.
revoke all on function public.pick_cached_questions(text, integer, integer, integer, uuid, integer, interval, integer)
  from public, anon, authenticated;
grant execute on function public.pick_cached_questions(text, integer, integer, integer, uuid, integer, interval, integer)
  to service_role;

-- 3) The app marks questions seen as they're shown, as the kid playing. Only
-- one of the signed-in grown-up's kids (anyone else's: nothing is written),
-- only questions in the bank, at most 20 a call (counted after unnest, so a
-- nested array can't slip more through), and not again within half an hour.
create or replace function public.mark_questions_seen(p_profile uuid, p_ids uuid[])
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.question_views (profile_id, question_id, shown)
  select p_profile, q.id, true
    from public.questions q
   where q.id in (select x from unnest(p_ids) as x limit 20)
     and exists (
       select 1 from public.profiles p
        where p.id = p_profile and p.parent_id = auth.uid()
     )
     and not exists (
       select 1 from public.question_views v
        where v.profile_id = p_profile
          and v.question_id = q.id
          and v.shown
          and v.seen_at > now() - interval '30 minutes'
     );
$$;

revoke execute on function public.mark_questions_seen(uuid, uuid[]) from public, anon;
grant execute on function public.mark_questions_seen(uuid, uuid[]) to authenticated;

insert into supabase_migrations.schema_migrations (version, name, statements)
values ('0015', 'fair_question_reuse', array[]::text[])
on conflict (version) do nothing;

-- ============================================================================
-- 0016_question_review.sql
-- ============================================================================
-- Hazel Quest — reviewing questions for kids (Act I launch review B10)
-- Run in the Supabase SQL Editor (or `supabase db push`) after 0015.
-- Re-runnable, like every migration (see CLAUDE.md → migrations rules).
--
-- Before this, one report from any family hid a question from everyone, for
-- good, and nobody looked at reports. Now:
--   * every question has a review status: 'active' (served), 'review' (held
--     back until a grown-up looks), 'retired' (never served again) or
--     'approved' (looked at and fine — served first);
--   * a "not OK for kids" report holds an active question back at once; an
--     approved one goes back to review once two families say so;
--   * any other report (wrong answer, confusing, difficulty) hides the
--     question from the reporting family only (the edge function), and holds
--     it back for everyone once three families have reported it;
--   * `question_review_queue` lists what needs a look, and `review_question`
--     records the decision. Both are for the project owner (service role /
--     SQL editor) only.

-- 1) A review status on every question.
alter table public.questions
  add column if not exists status text not null default 'active'
    constraint questions_status_check check (status in ('active', 'review', 'retired', 'approved'));
alter table public.questions add column if not exists reviewed_at timestamptz;
create index if not exists questions_topic_status_level_idx on public.questions (topic, status, level);

-- 2) Reports move a question into review.
create or replace function public.question_flag_review()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  families int;
  not_ok_families int;
begin
  select count(distinct p.parent_id),
         count(distinct p.parent_id) filter (where f.reason = 'not_for_kids')
    into families, not_ok_families
    from public.question_flags f
    join public.profiles p on p.id = f.profile_id
   where f.question_id = new.question_id;

  update public.questions q
     set status = 'review'
   where q.id = new.question_id
     and (
       (q.status = 'active' and (new.reason = 'not_for_kids' or families >= 3))
       or (q.status = 'approved' and not_ok_families >= 2)
     );
  return new;
end;
$$;
revoke execute on function public.question_flag_review() from public, anon, authenticated;

drop trigger if exists question_flag_review on public.question_flags;
create trigger question_flag_review
  after insert on public.question_flags
  for each row execute function public.question_flag_review();

-- 3) What needs a look: questions held back, and any with reports since they
--    were last reviewed — "not OK for kids" first, then by families.
create or replace view public.question_review_queue
with (security_invoker = true) as
select q.id,
       q.topic,
       q.level,
       q.status,
       q.text,
       q.options,
       q.correct_index,
       q.explanation,
       count(f.id) as reports,
       count(distinct p.parent_id) as families,
       count(f.id) filter (where f.reason = 'not_for_kids') as not_for_kids,
       array_remove(array_agg(distinct f.reason), null) as reasons,
       max(f.created_at) as last_report
  from public.questions q
  join public.question_flags f on f.question_id = q.id
  left join public.profiles p on p.id = f.profile_id
 where q.status <> 'retired'
   and (q.status = 'review' or f.created_at > coalesce(q.reviewed_at, '-infinity'::timestamptz))
 group by q.id
 order by (q.status = 'review') desc, not_for_kids desc, families desc, last_report desc;
revoke all on public.question_review_queue from public, anon, authenticated;
grant select on public.question_review_queue to service_role;

-- 4) Recording a review: approve (served first), retire (never again), or put
--    back to active.
create or replace function public.review_question(p_question uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_status not in ('active', 'approved', 'retired') then
    raise exception 'status must be active, approved or retired';
  end if;
  update public.questions set status = p_status, reviewed_at = now() where id = p_question;
  if not found then
    raise exception 'no such question';
  end if;
end;
$$;
revoke execute on function public.review_question(uuid, text) from public, anon, authenticated;
grant execute on function public.review_question(uuid, text) to service_role;

-- 5) The question picker (0015, #134) follows these rules too: only 'active'
--    and 'approved' questions, approved ones first, and a report hides a
--    question from the reporting family only (everyone else stops seeing it
--    through its status). Same signature and columns as 0015's, so the edge
--    function's call is unchanged; everything else it does — the age limit,
--    the per-topic seen window, the hour's hold, the lean to less-asked — is
--    as before.
create or replace function public.pick_cached_questions(
  p_topic      text,
  p_min_level  integer,
  p_max_level  integer,
  p_max_age    integer,
  p_profile    uuid,
  p_seen_limit integer,
  p_reserve    interval,
  p_limit      integer
)
returns table (
  id            uuid,
  level         smallint,
  text          text,
  options       jsonb,
  correct_index smallint,
  explanation   text,
  times_asked   integer,
  seen          boolean
)
language sql
set search_path = public
as $$
  with recent as (
    -- The kid's latest shown views of any topic, read newest first off the
    -- (profile_id, seen_at desc) index and capped, so a call costs the same
    -- however long they've played (no scan of their whole history).
    select v.question_id, v.seen_at
      from question_views v
     where v.profile_id = p_profile
       and v.shown
     order by v.seen_at desc
     limit greatest(p_seen_limit, 0) * 10
  ),
  shown as (
    select r.question_id
      from recent r
      join questions q on q.id = r.question_id
     where q.topic = p_topic
     -- A question shown again (a battle goes round its pool) counts once.
     group by r.question_id
     order by max(r.seen_at) desc
     limit greatest(p_seen_limit, 0)
  ),
  held as (
    select question_id from shown
    union
    select v.question_id
      from question_views v
     where v.profile_id = p_profile
       and not v.shown
       and v.seen_at > now() - p_reserve
  ),
  family as (
    -- Every kid of the grown-up this kid belongs to.
    select f.id
      from profiles f
     where f.parent_id = (select k.parent_id from profiles k where k.id = p_profile)
  )
  select q.id, q.level, q.text, q.options, q.correct_index, q.explanation, q.times_asked,
         (h.question_id is not null) as seen
    from questions q
    left join held h on h.question_id = q.id
   where q.topic = p_topic
     and q.level between p_min_level and p_max_level
     and q.status in ('active', 'approved')
     and (p_max_age is null or q.age is null or q.age <= p_max_age)
     and not exists (
       select 1 from question_flags fl
        where fl.question_id = q.id
          and fl.profile_id in (select id from family)
     )
   order by (h.question_id is not null),
            (q.status <> 'approved'),
            -- Weighted random order (Efraimidis–Spirakis): the smallest key
            -- wins; 1 - random() is never 0, so ln() always has an answer.
            -ln(1 - random()) * sqrt(1 + greatest(q.times_asked, 0))
   limit greatest(p_limit, 0);
$$;

revoke all on function public.pick_cached_questions(text, integer, integer, integer, uuid, integer, interval, integer)
  from public, anon, authenticated;
grant execute on function public.pick_cached_questions(text, integer, integer, integer, uuid, integer, interval, integer)
  to service_role;

insert into supabase_migrations.schema_migrations (version, name, statements)
values ('0016', 'question_review', array[]::text[])
on conflict (version) do nothing;

-- ============================================================================
-- 0017_question_age_window.sql
-- ============================================================================
-- Migration 0017 (#147): saved questions are reused within a year of the age
-- they were written for, both ways, and the review queue shows questions held
-- back without a report (the bank recheck's).
--
-- 1) The question writer now pitches a level to the child's age: level 9 for a
--    7-year-old is much easier than level 9 for an 11-year-old. 0015 only kept
--    out questions written for a child more than a year OLDER, so an
--    11-year-old at level 10 was mostly served questions written for 7- and
--    8-year-olds. The picker gains a lower edge (p_min_age), and a question
--    written for an older child is reused only at or below this kid's own
--    level (p_age, p_level), so a "two years ahead" stretch question never
--    reaches a younger kid above theirs. Questions saved before ages were
--    stored have none and stay in (the owner's call in #134). The three new
--    parameters default to null, which keeps 0016's behaviour, so the edge
--    function from before this migration still works against it.
-- 2) questions.review_note: why a question was held back by something other
--    than a family's report — `supabase/scripts/recheck-questions.ts` writes it.
-- 3) The review queue lists held-back questions with no reports too, their
--    note among the reasons. Same columns as 0016's view, so re-running 0016
--    from the bundle still works.

alter table public.questions add column if not exists review_note text;

create or replace view public.question_review_queue
with (security_invoker = true) as
select q.id,
       q.topic,
       q.level,
       q.status,
       q.text,
       q.options,
       q.correct_index,
       q.explanation,
       count(f.id) as reports,
       count(distinct p.parent_id) as families,
       count(f.id) filter (where f.reason = 'not_for_kids') as not_for_kids,
       array_remove(array_agg(distinct f.reason), null)
         || case when q.review_note is null then '{}'::text[] else array['recheck: ' || q.review_note] end
         as reasons,
       max(f.created_at) as last_report
  from public.questions q
  left join public.question_flags f on f.question_id = q.id
  left join public.profiles p on p.id = f.profile_id
 where q.status <> 'retired'
   and (q.status = 'review' or f.created_at > coalesce(q.reviewed_at, '-infinity'::timestamptz))
 group by q.id
 order by (q.status = 'review') desc, not_for_kids desc, families desc, last_report desc nulls last;
revoke all on public.question_review_queue from public, anon, authenticated;
grant select on public.question_review_queue to service_role;

-- The picker gains three parameters, so it's a new signature: drop 0016's.
drop function if exists public.pick_cached_questions(text, integer, integer, integer, uuid, integer, interval, integer);

create or replace function public.pick_cached_questions(
  p_topic      text,
  p_min_level  integer,
  p_max_level  integer,
  p_max_age    integer,
  p_profile    uuid,
  p_seen_limit integer,
  p_reserve    interval,
  p_limit      integer,
  p_min_age    integer default null,
  p_age        integer default null,
  p_level      integer default null
)
returns table (
  id            uuid,
  level         smallint,
  text          text,
  options       jsonb,
  correct_index smallint,
  explanation   text,
  times_asked   integer,
  seen          boolean
)
language sql
set search_path = public
as $$
  with recent as (
    -- The kid's latest shown views of any topic, read newest first off the
    -- (profile_id, seen_at desc) index and capped, so a call costs the same
    -- however long they've played (no scan of their whole history).
    select v.question_id, v.seen_at
      from question_views v
     where v.profile_id = p_profile
       and v.shown
     order by v.seen_at desc
     limit greatest(p_seen_limit, 0) * 10
  ),
  shown as (
    select r.question_id
      from recent r
      join questions q on q.id = r.question_id
     where q.topic = p_topic
     -- A question shown again (a battle goes round its pool) counts once.
     group by r.question_id
     order by max(r.seen_at) desc
     limit greatest(p_seen_limit, 0)
  ),
  held as (
    select question_id from shown
    union
    select v.question_id
      from question_views v
     where v.profile_id = p_profile
       and not v.shown
       and v.seen_at > now() - p_reserve
  ),
  family as (
    -- Every kid of the grown-up this kid belongs to.
    select f.id
      from profiles f
     where f.parent_id = (select k.parent_id from profiles k where k.id = p_profile)
  )
  select q.id, q.level, q.text, q.options, q.correct_index, q.explanation, q.times_asked,
         (h.question_id is not null) as seen
    from questions q
    left join held h on h.question_id = q.id
   where q.topic = p_topic
     and q.level between p_min_level and p_max_level
     and q.status in ('active', 'approved')
     and (p_max_age is null or q.age is null or q.age <= p_max_age)
     and (p_min_age is null or q.age is null or q.age >= p_min_age)
     -- A question written for an older child: only at or below this kid's level.
     and (p_age is null or p_level is null or q.age is null or q.age <= p_age or q.level <= p_level)
     and not exists (
       select 1 from question_flags fl
        where fl.question_id = q.id
          and fl.profile_id in (select id from family)
     )
   order by (h.question_id is not null),
            (q.status <> 'approved'),
            -- Weighted random order (Efraimidis–Spirakis): the smallest key
            -- wins; 1 - random() is never 0, so ln() always has an answer.
            -ln(1 - random()) * sqrt(1 + greatest(q.times_asked, 0))
   limit greatest(p_limit, 0);
$$;

revoke all on function public.pick_cached_questions(text, integer, integer, integer, uuid, integer, interval, integer, integer, integer, integer)
  from public, anon, authenticated;
grant execute on function public.pick_cached_questions(text, integer, integer, integer, uuid, integer, interval, integer, integer, integer, integer)
  to service_role;

insert into supabase_migrations.schema_migrations (version, name, statements)
values ('0017', 'question_age_window', array[]::text[])
on conflict (version) do nothing;

-- ============================================================================
-- 0018_question_checks.sql
-- ============================================================================
-- Migration 0018 (#147): every question is checked once, and a family's report
-- checks it again.
--
-- 1) questions.checked_version / checked_at: the rules version a question was
--    last checked under, and when. New questions are saved with it (they pass
--    the checks before they're saved); the recheck script
--    (supabase/scripts/recheck-questions.ts) sets it on the saved bank and
--    skips anything already checked under the current version, so each
--    question is checked once per version of the rules.
-- 2) questions.report_checked_at and claim_report_check(): a report starts a
--    check (the edge function's `check-report` action, Claude Haiku then a
--    stronger model). The claim is atomic and only succeeds when the family
--    reported the question since its last check, and while the family has
--    made no more than p_daily_cap reports in the last day — so each report
--    checks a question at most once, and a family can't run up the bill. With
--    p_parent null (the recheck script's sweep) any family's report counts and
--    there's no cap.
-- 3) pending_report_checks(): questions with a report newer than their last
--    check — reports the edge function never got to (an app closed, a check
--    that failed, a family over its cap) — for the recheck script's
--    `--reported` run.

alter table public.questions add column if not exists checked_version smallint;
alter table public.questions add column if not exists checked_at timestamptz;
alter table public.questions add column if not exists report_checked_at timestamptz;

create or replace function public.claim_report_check(
  p_question  uuid,
  p_parent    uuid,
  p_daily_cap integer
)
returns table (
  id            uuid,
  text          text,
  options       jsonb,
  correct_index smallint,
  explanation   text,
  age           smallint
)
language sql
set search_path = public
as $$
  with family as (
    select f.id from profiles f where f.parent_id = p_parent
  ),
  newest as (
    select max(fl.created_at) as at
      from question_flags fl
     where fl.question_id = p_question
       and (p_parent is null or fl.profile_id in (select id from family))
  ),
  today as (
    select count(*) as n
      from question_flags fl
     where fl.profile_id in (select id from family)
       and fl.created_at > now() - interval '1 day'
  )
  update questions q
     -- A check covers every report so far, whoever made it.
     set report_checked_at = greatest(now(), (select max(fl.created_at) from question_flags fl
                                              where fl.question_id = p_question))
   where q.id = p_question
     and q.status <> 'retired'
     and (select at from newest) is not null
     and (select at from newest) > coalesce(q.report_checked_at, '-infinity'::timestamptz)
     and (p_parent is null or (select n from today) <= p_daily_cap)
  returning q.id, q.text, q.options, q.correct_index, q.explanation, q.age;
$$;

create or replace function public.pending_report_checks(p_limit integer)
returns table (id uuid)
language sql
stable
set search_path = public
as $$
  select q.id
    from questions q
   where q.status <> 'retired'
     and exists (
       select 1 from question_flags fl
        where fl.question_id = q.id
          and fl.created_at > coalesce(q.report_checked_at, '-infinity'::timestamptz)
     )
   order by q.id
   limit greatest(p_limit, 0);
$$;

revoke all on function public.claim_report_check(uuid, uuid, integer) from public, anon, authenticated;
grant execute on function public.claim_report_check(uuid, uuid, integer) to service_role;
revoke all on function public.pending_report_checks(integer) from public, anon, authenticated;
grant execute on function public.pending_report_checks(integer) to service_role;

